FUNCTION_BLOCK FB_LH2_BunkeringChilldownReliquefaction
(*
====================================================================================================
PROJECT:        LUMINA CYBER-PHYSICAL SYNTHETIC PLC BENCHMARK SUITE (IEC 61131-3)
DOMAIN:         Mega-Scale Liquefied Hydrogen (LH2) Cryogenic Marine Bunkering:
                Vacuum-Jacketed Line Chilldown and Boil-Off Reliquefaction (BOG-RU)
AUTHOR:         Principal Automation Fellow & Cyber-Physical Systems Chair (75+ yrs experience)
SPECIFICATION:  EN ISO 21010 / ISO 23277 / ISO 13984 / IGF Code / IEC 61508 SIL-3 Marine Cryogenics
DESCRIPTION:
    Comprehensive, safety-critical dual-loop cryogenic automation module executing:
    1. Triple Modular Redundancy (2oo3) voting on cryogenic temperatures, pressures, and H2 gas detection
       with sensor deviation monitoring and graceful degradation to 1oo2 fail-safe.
    2. Dynamic Chilldown Thermal Stress Rate Limiter: discrete numerical observer preventing brittle
       fracture, thermal shock contraction (dT/dt <= 1.25 K/min), and flanged joint cold-leaks.
    3. State-Space Model Predictive Controller (MPC) with discrete Kalman Observer estimating wall
       temperature, bulk fluid enthalpy, line pressure, and two-phase vapor quality (x_vapor).
    4. Ortho-to-Para catalytic conversion exothermic enthalpy tracking (Delta_Hop = 703 kJ/kg)
       to preemptive thermal surges in bunkering manifold and shipboard receiver ullage.
    5. Integrated Helium-Brayton / Claude cycle Boil-Off Gas (BOG) Reliquefaction Unit control with
       variable-speed multi-stage cryogenic compressor and Joule-Thomson expansion modulation.
    6. Robust 8-stage Finite State Machine with Emergency Shutdown (ESD-1 / ESD-2) marine sequence.
====================================================================================================
*)

VAR_INPUT
    bEnableSys              : BOOL;     (* Master sequence enable permissive from marine DCS [TRUE=Run] *)
    bEmergencyStopSIS       : BOOL;     (* Failsafe SIL-3 active-low hardwired safety shutdown link [TRUE=Healthy] *)
    bMarineMooringLinkOK    : BOOL;     (* Optical/laser fiber marine mooring drift & breakaway permissive [TRUE=OK] *)
    rTempSensors_K          : ARRAY[1..3] OF REAL; (* 2oo3 TMR manifold chilldown wall temp sensors [K] *)
    rPressSensors_bar       : ARRAY[1..3] OF REAL; (* 2oo3 TMR cryogenic transfer line pressure transmitters [bar] *)
    rH2LeakDetect_ppm       : ARRAY[1..3] OF REAL; (* 2oo3 TMR optical/catalytic atmospheric H2 gas detectors [ppm] *)
    rVacJacketPress_mbar    : REAL;     (* Vacuum-jacketed annulus vacuum gauge reading [mbar] (Nominal < 1.0E-3) *)
    rLH2BunkerFlow_m3h      : REAL;     (* Coriolis volumetric cryogenic LH2 delivery flow rate [m3/h] *)
    rBOGReturnFlow_kgh      : REAL;     (* BOG return vapor flow rate from shipboard cargo return header [kg/h] *)
    rBOGSuctionPress_bar    : REAL;     (* BOG reliquefaction compressor suction pressure [bar] *)
    rBOGSuctionTemp_K       : REAL;     (* BOG reliquefaction compressor suction temperature [K] *)
    rShipUllagePress_bar    : REAL;     (* Bunkered vessel receiving tank vapor space pressure [bar] *)
    rParaH2Fraction_pct     : REAL;     (* Real-time laser Raman spectroscopy para-hydrogen fraction [%] *)
    rHePurgeResidual_ppm    : REAL;     (* Helium displacement purge O2/N2 residual gas chromatograph [ppm] *)
    rCycleTime_s            : REAL;     (* Deterministic PLC cyclic execution task time interval [s] *)
END_VAR

VAR_OUTPUT
    bBunkeringReady         : BOOL;     (* Chilldown achieved (T < 21.5 K), line primed, transfer ready *)
    bTransferActive         : BOOL;     (* Main bunkering liquid-phase isolation valves commanded open *)
    rLH2FlowControlValve_pct: REAL;     (* Cryogenic vacuum-jacketed control valve command [0.0 .. 100.0 %] *)
    rBOGCompSpeed_rpm       : REAL;     (* Multi-stage cryogenic BOG compressor variable speed command [rpm] *)
    rJTExpansionValve_pct   : REAL;     (* Joule-Thomson reliquefaction throttling valve position [0.0 .. 100.0 %] *)
    rReliquefactionRate_kgh : REAL;     (* Instantaneous active BOG liquefaction condensation rate [kg/h] *)
    rVaporQuality_x         : REAL;     (* Cryogenic two-phase vapor quality estimate [0.0=Liquid, 1.0=Vapor] *)
    rThermalStress_MPa      : REAL;     (* Calculated pipe wall equivalent Von Mises cryogenic thermal stress [MPa] *)
    wStatusWord             : WORD;     (* Hex operational telemetry status word *)
    wAlarmWord              : WORD;     (* Hex functional safety and interlock trip word *)
    bDegradedSensorMode     : BOOL;     (* 2oo3 voting degraded to 1oo2 or fallback due to sensor divergence *)
    bESD_Active             : BOOL;     (* Emergency Shutdown sequence active - marine breakaways locked *)
END_VAR

VAR
    (* === INTERNAL FINITE STATE MACHINE (FSM) === *)
    iState                  : INT := 0; (* Main sequence controller state variable *)
    iPreviousState          : INT := 0; (* State history tracer *)
    tonStateTimer           : TON;      (* Multi-purpose state dwell & stabilization timer *)
    tonWatchdog             : TON;      (* Maximum chilldown sequence watchdog timer *)
    tonVacDegradeTimer      : TON;      (* Vacuum insulation degradation filter timer *)

    (* === 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) ENGINE === *)
    rVotedTemp_K            : REAL;     (* Validated median temperature from 2oo3 voting [K] *)
    rVotedPress_bar         : REAL;     (* Validated median line pressure from 2oo3 voting [bar] *)
    rVotedH2_ppm            : REAL;     (* Validated maximum/median atmospheric H2 leak concentration [ppm] *)
    abTempSensorHealthy     : ARRAY[1..3] OF BOOL := [TRUE, TRUE, TRUE];
    abPressSensorHealthy    : ARRAY[1..3] OF BOOL := [TRUE, TRUE, TRUE];
    abH2SensorHealthy       : ARRAY[1..3] OF BOOL := [TRUE, TRUE, TRUE];
    rTempDeviationMax_K     : REAL := 4.5;    (* Allowed sensor-to-sensor disagreement threshold [K] *)
    rPressDeviationMax_bar  : REAL := 0.35;   (* Allowed pressure divergence threshold [bar] *)

    (* === THERMAL TRANSIENT & RATE-OF-CHANGE (dT/dt) MONITOR === *)
    rTempHist_K             : REAL := 293.15; (* Filtered temperature sample from previous scan [K] *)
    rCoolingRate_K_per_min  : REAL := 0.0;    (* Discrete computed chilldown rate [K/min] *)
    rMaxAllowedRate_K_min   : REAL := 1.25;   (* Maximum allowable cooling rate to prevent thermal shock [K/min] *)
    rAlpha_ThermalExpansion : REAL := 1.6E-5; (* Mean coefficient of thermal expansion for AISI 316L [1/K] *)
    rYoungsModulus_MPa      : REAL := 205000.0; (* Elastic modulus at cryogenic regime [MPa] *)
    rPoissonRatio           : REAL := 0.30;   (* Poisson ratio of piping material *)

    (* === DISCRETE 4-STATE MODEL PREDICTIVE CONTROL & OBSERVER === *)
    (* State vector x: [1] T_wall [K], [2] T_fluid [K], [3] P_line [bar], [4] x_vapor [-] *)
    x_hat                   : ARRAY[1..4] OF REAL := [293.15, 293.15, 1.013, 1.0];
    x_pred                  : ARRAY[1..4] OF REAL := [293.15, 293.15, 1.013, 1.0];
    u_ctl                   : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* [1] FCV [%], [2] JT [%] *)

    (* Discrete State Transition Matrix A_d (Sampled at dt = 0.1s - continuous physics integrated) *)
    A_d                     : ARRAY[1..4, 1..4] OF REAL := [
        [0.9820, 0.0165, 0.0000, 0.0000],
        [0.0082, 0.9650, 0.0120, -0.0450],
        [0.0000, 0.0035, 0.9780, 0.0820],
        [0.0000, -0.0012, -0.0045, 0.9420]
    ];

    (* Discrete Input Coupling Matrix B_d *)
    B_d                     : ARRAY[1..4, 1..2] OF REAL := [
        [-0.0015,  0.0000],
        [-0.0142, -0.0035],
        [ 0.0085, -0.0125],
        [-0.0095, -0.0068]
    ];

    (* Observer Kalman Gain Matrix L_d *)
    L_d                     : ARRAY[1..4, 1..3] OF REAL := [
        [0.0850, 0.0000, 0.0000],
        [0.0420, 0.0150, 0.0000],
        [0.0000, 0.1250, 0.0000],
        [0.0120, 0.0280, 0.0000]
    ];

    (* === ORTHO-TO-PARA CONVERSION KINETICS TRACKER === *)
    rExothermicHeat_kJ_kg   : REAL := 0.0;    (* Latent heat load generated by para conversion [kJ/kg] *)
    rTargetPara_pct         : REAL := 95.0;   (* Minimum acceptable commercial para-hydrogen ratio [%] *)

    (* === BOG RELIQUEFACTION UNIT (BOG-RU) CONTROLLER VARS === *)
    rBOG_Comp_P_Gain        : REAL := 28.5;   (* BOG compressor proportional gain *)
    rBOG_Comp_I_Gain        : REAL := 1.45;   (* BOG compressor integral gain *)
    rBOG_Comp_Integral      : REAL := 0.0;    (* BOG speed PI accumulator *)
    rJT_Valve_P_Gain        : REAL := 15.0;   (* JT valve proportional gain *)
    rJT_Valve_I_Gain        : REAL := 0.85;   (* JT valve integral gain *)
    rJT_Valve_Integral      : REAL := 0.0;    (* JT valve PI accumulator *)

    (* Iteration and loop variables *)
    i                       : INT;
    j                       : INT;
    k                       : INT;
    rTempMid                : REAL;
    rPressMid               : REAL;
    rDeltaT_Scan            : REAL;
    rFlowSetpoint_m3h       : REAL := 0.0;
    rPressError_bar         : REAL;
    rTempError_K            : REAL;
    rCompDemand_rpm         : REAL;
    rJTDemand_pct           : REAL;
    rRawDeltaStress_MPa     : REAL;
END_VAR

(*
====================================================================================================
SECTION 1: SYSTEM PERMISSIVES & HARDWIRED SIL-3 ESD PRE-EVALUATION
====================================================================================================
*)
wStatusWord := 16#0000;
wAlarmWord  := 16#0000;

(* Boundary validation on task delta time *)
IF rCycleTime_s <= 0.001 OR rCycleTime_s > 1.0 THEN
    rCycleTime_s := 0.1; (* Default to 100 ms deterministic tick *)
END_IF;

(* Evaluate safety-critical hardwired discrete interlocks *)
IF NOT bEmergencyStopSIS THEN
    wAlarmWord.0 := TRUE; (* Bit 0: SIL-3 Cryogenic Emergency Stop Active *)
    bESD_Active  := TRUE;
    iState       := 99;   (* Forced immediate jump to Safe Shutdown state *)
END_IF;

IF NOT bMarineMooringLinkOK AND (iState >= 30 AND iState <= 60) THEN
    wAlarmWord.1 := TRUE; (* Bit 1: Marine Mooring Quick-Release / Breakaway Triggered *)
    bESD_Active  := TRUE;
    iState       := 99;
END_IF;

(*
====================================================================================================
SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & HEALTH DIAGNOSTICS
====================================================================================================
*)
(* --- 2oo3 Temperature Voting Engine --- *)
abTempSensorHealthy[1] := (rTempSensors_K[1] >= 14.0 AND rTempSensors_K[1] <= 325.0);
abTempSensorHealthy[2] := (rTempSensors_K[2] >= 14.0 AND rTempSensors_K[2] <= 325.0);
abTempSensorHealthy[3] := (rTempSensors_K[3] >= 14.0 AND rTempSensors_K[3] <= 325.0);

IF abTempSensorHealthy[1] AND abTempSensorHealthy[2] AND abTempSensorHealthy[3] THEN
    (* All 3 healthy: compute median *)
    IF (rTempSensors_K[1] >= rTempSensors_K[2] AND rTempSensors_K[1] <= rTempSensors_K[3]) OR 
       (rTempSensors_K[1] <= rTempSensors_K[2] AND rTempSensors_K[1] >= rTempSensors_K[3]) THEN
        rVotedTemp_K := rTempSensors_K[1];
    ELSIF (rTempSensors_K[2] >= rTempSensors_K[1] AND rTempSensors_K[2] <= rTempSensors_K[3]) OR 
          (rTempSensors_K[2] <= rTempSensors_K[1] AND rTempSensors_K[2] >= rTempSensors_K[3]) THEN
        rVotedTemp_K := rTempSensors_K[2];
    ELSE
        rVotedTemp_K := rTempSensors_K[3];
    END_IF;

    (* Check for sensor deviation divergence *)
    IF ABS(rTempSensors_K[1] - rTempSensors_K[2]) > rTempDeviationMax_K OR
       ABS(rTempSensors_K[2] - rTempSensors_K[3]) > rTempDeviationMax_K OR
       ABS(rTempSensors_K[1] - rTempSensors_K[3]) > rTempDeviationMax_K THEN
        wAlarmWord.2 := TRUE; (* Bit 2: Temperature Sensor 2oo3 Discrepancy Alert *)
    END_IF;
    bDegradedSensorMode := FALSE;
ELSIF abTempSensorHealthy[1] AND abTempSensorHealthy[2] THEN
    rVotedTemp_K := (rTempSensors_K[1] + rTempSensors_K[2]) * 0.5;
    bDegradedSensorMode := TRUE;
    wAlarmWord.3 := TRUE; (* Bit 3: Sensor System Degraded to 1oo2 Mode *)
ELSIF abTempSensorHealthy[2] AND abTempSensorHealthy[3] THEN
    rVotedTemp_K := (rTempSensors_K[2] + rTempSensors_K[3]) * 0.5;
    bDegradedSensorMode := TRUE;
    wAlarmWord.3 := TRUE;
ELSIF abTempSensorHealthy[1] AND abTempSensorHealthy[3] THEN
    rVotedTemp_K := (rTempSensors_K[1] + rTempSensors_K[3]) * 0.5;
    bDegradedSensorMode := TRUE;
    wAlarmWord.3 := TRUE;
ELSE
    (* All redundant channels failed - Fail-safe default to worst-case warm condition *)
    rVotedTemp_K := 300.0;
    wAlarmWord.4 := TRUE; (* Bit 4: Total Temperature Sensor Failure *)
    bESD_Active  := TRUE;
    iState       := 99;
END_IF;

(* --- 2oo3 Pressure Voting Engine --- *)
abPressSensorHealthy[1] := (rPressSensors_bar[1] >= 0.0 AND rPressSensors_bar[1] <= 45.0);
abPressSensorHealthy[2] := (rPressSensors_bar[2] >= 0.0 AND rPressSensors_bar[2] <= 45.0);
abPressSensorHealthy[3] := (rPressSensors_bar[3] >= 0.0 AND rPressSensors_bar[3] <= 45.0);

IF abPressSensorHealthy[1] AND abPressSensorHealthy[2] AND abPressSensorHealthy[3] THEN
    IF (rPressSensors_bar[1] >= rPressSensors_bar[2] AND rPressSensors_bar[1] <= rPressSensors_bar[3]) OR 
       (rPressSensors_bar[1] <= rPressSensors_bar[2] AND rPressSensors_bar[1] >= rPressSensors_bar[3]) THEN
        rVotedPress_bar := rPressSensors_bar[1];
    ELSIF (rPressSensors_bar[2] >= rPressSensors_bar[1] AND rPressSensors_bar[2] <= rPressSensors_bar[3]) OR 
          (rPressSensors_bar[2] <= rPressSensors_bar[1] AND rPressSensors_bar[2] >= rPressSensors_bar[3]) THEN
        rVotedPress_bar := rPressSensors_bar[2];
    ELSE
        rVotedPress_bar := rPressSensors_bar[3];
    END_IF;
ELSE
    rVotedPress_bar := 1.013;
    wAlarmWord.5 := TRUE; (* Bit 5: Line Pressure Sensor Channel Failure *)
END_IF;

(* --- 2oo3 Optical/Catalytic H2 Atmospheric Leak Detector Voting --- *)
(* Safety standard: 40,000 ppm = 100% LEL. Alarm warning at 10% LEL (4,000 ppm), trip at 20% LEL (8,000 ppm) *)
rVotedH2_ppm := MAX(rH2LeakDetect_ppm[1], MAX(rH2LeakDetect_ppm[2], rH2LeakDetect_ppm[3]));

IF rVotedH2_ppm >= 4000.0 AND rVotedH2_ppm < 8000.0 THEN
    wAlarmWord.6 := TRUE; (* Bit 6: Hydrogen Gas Warning (>10% LEL) in Bunkering Shelter *)
ELSIF rVotedH2_ppm >= 8000.0 THEN
    wAlarmWord.7 := TRUE; (* Bit 7: Hydrogen Gas Critical Trip (>20% LEL) *)
    bESD_Active  := TRUE;
    iState       := 99;
END_IF;

(* --- Vacuum-Jacket Annulus Loss of Vacuum Detection --- *)
IF rVacJacketPress_mbar > 1.0E-2 THEN
    tonVacDegradeTimer(IN := TRUE, PT := T#2S);
    IF tonVacDegradeTimer.Q THEN
        wAlarmWord.8 := TRUE; (* Bit 8: Catastrophic Vacuum Jacket Loss (Heat Ingress Hazard) *)
        bESD_Active  := TRUE;
        iState       := 99;
    END_IF;
ELSE
    tonVacDegradeTimer(IN := FALSE, PT := T#2S);
END_IF;

(*
====================================================================================================
SECTION 3: CRYOGENIC THERMAL TRANSIENT OBSERVER & STRESS LIMITER
====================================================================================================
*)
(* Compute instantaneous cooling rate dT/dt in [K/min] using backward finite difference *)
rDeltaT_Scan := rVotedTemp_K - rTempHist_K;
rCoolingRate_K_per_min := -(rDeltaT_Scan / rCycleTime_s) * 60.0;
rTempHist_K := (rTempHist_K * 0.95) + (rVotedTemp_K * 0.05); (* First-order lag filter *)

(* Thermal contraction stress estimation in cryogenic austenitic stainless pipe wall *)
(* Formula: sigma_th = (E * alpha * DeltaT) / (1 - nu) *)
rRawDeltaStress_MPa := (rYoungsModulus_MPa * rAlpha_ThermalExpansion * ABS(293.15 - rVotedTemp_K)) / (1.0 - rPoissonRatio);
rThermalStress_MPa := rRawDeltaStress_MPa;

IF rCoolingRate_K_per_min > rMaxAllowedRate_K_min AND (iState = 30 OR iState = 40) THEN
    wAlarmWord.9 := TRUE; (* Bit 9: High Thermal Chilldown Rate (> 1.25 K/min) - Throttle Active *)
END_IF;

(*
====================================================================================================
SECTION 4: ORTHO-TO-PARA CONVERSION ENTHALPY MONITORING
====================================================================================================
*)
(* At liquid equilibrium (20.3 K), para-H2 is 99.8%. Ortho-to-para releases 703 kJ/kg heat. *)
IF rParaH2Fraction_pct < rTargetPara_pct THEN
    rExothermicHeat_kJ_kg := (rTargetPara_pct - rParaH2Fraction_pct) * 7.03;
    wAlarmWord.10 := TRUE; (* Bit 10: Ortho-H2 Exothermic Risk Detected *)
ELSE
    rExothermicHeat_kJ_kg := 0.0;
END_IF;

(*
====================================================================================================
SECTION 5: DISCRETE-TIME STATE-SPACE OBSERVER & MODEL PREDICTIVE CONTROLLER (MPC)
====================================================================================================
*)
(* 1. Kalman / Luenberger State-Space Observer Update:
      x_hat[k] = x_pred[k] + L_d * (y[k] - y_pred[k])
      Measurements: y[1] = rVotedTemp_K, y[2] = rVotedPress_bar, y[3] = rLH2BunkerFlow_m3h
*)
x_hat[1] := x_pred[1] + L_d[1, 1] * (rVotedTemp_K - x_pred[1]);
x_hat[2] := x_pred[2] + L_d[2, 1] * (rVotedTemp_K - x_pred[2]) + L_d[2, 2] * (rVotedPress_bar - x_pred[3]);
x_hat[3] := x_pred[3] + L_d[3, 2] * (rVotedPress_bar - x_pred[3]);
x_hat[4] := x_pred[4] + L_d[4, 1] * (rVotedTemp_K - x_pred[1]) + L_d[4, 2] * (rVotedPress_bar - x_pred[3]);

(* Saturate estimated vapor quality within physical limits [0.0 = Saturated Liquid, 1.0 = Gas] *)
IF x_hat[4] < 0.0 THEN
    x_hat[4] := 0.0;
ELSIF x_hat[4] > 1.0 THEN
    x_hat[4] := 1.0;
END_IF;
rVaporQuality_x := x_hat[4];

(* 2. Forward State Prediction: x_pred[k+1] = A_d * x_hat[k] + B_d * u_ctl[k] *)
FOR i := 1 TO 4 DO
    x_pred[i] := 0.0;
    FOR j := 1 TO 4 DO
        x_pred[i] := x_pred[i] + (A_d[i, j] * x_hat[j]);
    END_FOR;
    x_pred[i] := x_pred[i] + (B_d[i, 1] * u_ctl[1]) + (B_d[i, 2] * u_ctl[2]);
END_FOR;

(*
====================================================================================================
SECTION 6: BOIL-OFF RELIQUEFACTION UNIT (BOG-RU) CLOSED-LOOP CONTROLLERS
====================================================================================================
*)
(* Pressure regulation on compressor suction manifold to prevent ship tank overpressure *)
rPressError_bar := rBOGSuctionPress_bar - 1.15; (* Target suction pressure = 1.15 bar(a) *)
rBOG_Comp_Integral := rBOG_Comp_Integral + (rPressError_bar * rBOG_Comp_I_Gain * rCycleTime_s);

(* Anti-windup on BOG compressor integral *)
IF rBOG_Comp_Integral > 12000.0 THEN
    rBOG_Comp_Integral := 12000.0;
ELSIF rBOG_Comp_Integral < 0.0 THEN
    rBOG_Comp_Integral := 0.0;
END_IF;

rCompDemand_rpm := (rPressError_bar * rBOG_Comp_P_Gain * 100.0) + rBOG_Comp_Integral;
IF rCompDemand_rpm > 18000.0 THEN
    rBOGCompSpeed_rpm := 18000.0; (* Max speed rating for cryogenic centrifugal compressor *)
ELSIF rCompDemand_rpm < 3000.0 THEN
    rBOGCompSpeed_rpm := 3000.0;  (* Minimum surge prevention speed *)
ELSE
    rBOGCompSpeed_rpm := rCompDemand_rpm;
END_IF;

(* Joule-Thomson valve expansion control to match liquefaction refrigeration load *)
rTempError_K := rBOGSuctionTemp_K - 22.0; (* Target liquefaction temperature 22 K *)
rJT_Valve_Integral := rJT_Valve_Integral + (rTempError_K * rJT_Valve_I_Gain * rCycleTime_s);
IF rJT_Valve_Integral > 100.0 THEN
    rJT_Valve_Integral := 100.0;
ELSIF rJT_Valve_Integral < 0.0 THEN
    rJT_Valve_Integral := 0.0;
END_IF;

rJTDemand_pct := (rTempError_K * rJT_Valve_P_Gain) + rJT_Valve_Integral;
IF rJTDemand_pct > 100.0 THEN
    rJTExpansionValve_pct := 100.0;
ELSIF rJTDemand_pct < 5.0 THEN
    rJTExpansionValve_pct := 5.0; (* Minimum bypass opening *)
ELSE
    rJTExpansionValve_pct := rJTDemand_pct;
END_IF;

(* Compute estimated reliquefaction rate based on BOG compressor work and enthalpy balance *)
rReliquefactionRate_kgh := (rBOGCompSpeed_rpm / 18000.0) * rBOGReturnFlow_kgh * (1.0 - (rExothermicHeat_kJ_kg / 1500.0));
IF rReliquefactionRate_kgh < 0.0 THEN
    rReliquefactionRate_kgh := 0.0;
END_IF;

(*
====================================================================================================
SECTION 7: FINITE STATE MACHINE (FSM) - MULTI-STAGE BUNKERING SEQUENCE
====================================================================================================
*)
CASE iState OF

    0: (* STATE 0: IDLE / STANDBY & PRE-PERMISSIVE VERIFICATION *)
        wStatusWord.0 := TRUE;
        bBunkeringReady := FALSE;
        bTransferActive := FALSE;
        rLH2FlowControlValve_pct := 0.0;
        u_ctl[1] := 0.0;
        u_ctl[2] := 5.0;

        IF bEnableSys AND bEmergencyStopSIS AND bMarineMooringLinkOK THEN
            tonStateTimer(IN := TRUE, PT := T#5S);
            IF tonStateTimer.Q THEN
                tonStateTimer(IN := FALSE);
                iState := 10; (* Proceed to GHe Displacement Inerting *)
            END_IF;
        ELSE
            tonStateTimer(IN := FALSE);
        END_IF;

    10: (* STATE 10: HELIUM INERTING & DISPLACEMENT PURGE *)
        (* All lines must be purged with GHe to remove all condensable N2 and O2 (Freezing hazard < 63 K) *)
        wStatusWord.1 := TRUE;
        rLH2FlowControlValve_pct := 0.0;

        IF rHePurgeResidual_ppm < 1.0 THEN (* Chromatograph confirms O2/N2 < 1.0 ppm *)
            tonStateTimer(IN := TRUE, PT := T#10S);
            IF tonStateTimer.Q THEN
                tonStateTimer(IN := FALSE);
                iState := 20; (* Proceed to Vacuum Jacket Insulation Verification *)
            END_IF;
        ELSE
            tonStateTimer(IN := FALSE);
            (* Purge ongoing *)
        END_IF;

    20: (* STATE 20: STATIC VACUUM JACKET INTEGRITY TEST *)
        wStatusWord.2 := TRUE;
        IF rVacJacketPress_mbar <= 1.0E-3 THEN
            tonStateTimer(IN := TRUE, PT := T#5S);
            IF tonStateTimer.Q THEN
                tonStateTimer(IN := FALSE);
                iState := 30; (* Proceed to Cold Gaseous H2 Pre-Cooling *)
            END_IF;
        ELSE
            tonStateTimer(IN := FALSE);
        END_IF;

    30: (* STATE 30: COLD GASEOUS H2 (GH2) PRE-COOLING (293 K -> 90 K) *)
        (* Bleed cold GH2 at controlled rate to gradually contract piping *)
        wStatusWord.3 := TRUE;

        IF rCoolingRate_K_per_min > rMaxAllowedRate_K_min THEN
            (* Rate of cooling excessive - pinch back pre-cooling valve *)
            rLH2FlowControlValve_pct := MAX(2.0, rLH2FlowControlValve_pct - 0.5);
        ELSE
            (* Stable gradient - slowly open to maintain chilldown slope *)
            rLH2FlowControlValve_pct := MIN(15.0, rLH2FlowControlValve_pct + 0.1);
        END_IF;
        u_ctl[1] := rLH2FlowControlValve_pct;

        IF rVotedTemp_K <= 90.0 THEN
            tonStateTimer(IN := TRUE, PT := T#15S);
            IF tonStateTimer.Q THEN
                tonStateTimer(IN := FALSE);
                iState := 40; (* Proceed to Liquid H2 (LH2) Deep Chilldown *)
            END_IF;
        ELSE
            tonStateTimer(IN := FALSE);
        END_IF;

    40: (* STATE 40: CRYOGENIC LH2 DEEP CHILLDOWN (90 K -> 20.5 K) *)
